#include "ark/agent.hpp"
#include "ark/usage.hpp"
#include "ark/iteration_history.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace ark;using V=arkjson::Value;
namespace {
void check(bool yes,const char* why){if(!yes)throw std::runtime_error(why);}
V json(const char* text){V value;check(arkjson::parse(text,value),"test JSON");return value;}
V data(const V& response){check(!response.find("isError")->b,"accepted tool response");return *response.find("structuredContent");}
void base(AgentSession& s){data(s.call("doc_apply",json(R"({"expected_revision":0,"commands":[{"op":"feature.add","type":"tube","name":"Host stock","p":{"section":"rect","width":60,"height":40,"wall":3,"tail":200}},{"op":"feature.add","type":"native_solid","name":"Host","inputs":[1],"native":{"op":"transform"},"p":{"tx":0}},{"op":"feature.add","type":"tube","name":"Brace stock","p":{"section":"rect","width":20,"height":16,"wall":2,"tail":100}},{"op":"feature.add","type":"native_solid","name":"Brace","inputs":[3],"native":{"op":"transform"},"p":{"ry":-90,"tx":100,"ty":9}}]})")));}
void custody(){
 AgentSession s;base(s);const auto before=documentToJson(s.document);const auto bad=json(R"({"expected_revision":1,"commands":[{"op":"feature.add","type":"native_solid","name":"Invalid bounded fit","inputs":[4,2],"native":{"op":"tube_end_fit","mode":"envelope","end":"start"},"p":{"max_extension":-1}}]})");
 auto failed=s.call("doc_apply",bad);check(failed.find("isError")->b&&failed.find("structuredContent")->find("failure_id"),"real geometric rejection captured");const auto id=*failed.find("structuredContent")->find("failure_id");auto repeated=s.call("doc_apply",bad);check(repeated.find("structuredContent")->find("repeat_count")->num==2&&repeated.find("structuredContent")->find("previous_failure_id")->str==id.str,"identical attempts produce repeated-failure evidence without retry");
 auto info=data(s.call("failure_info",V::makeObj()));check(info.find("records")->arr.size()==2&&info.dump().find("brep_base64")==std::string::npos&&info.dump().find("\"baseline\"")==std::string::npos,"default local record listing excludes private full baseline");
 V replay=V::makeObj();replay.set("id",id);replay.set("expected_revision",V::makeNum(1));auto proof=data(s.call("failure_replay",replay));check(proof.find("rejected")->b&&proof.find("same_error")->b&&proof.find("live_document_unchanged")->b&&documentToJson(s.document)==before,"same exact failed fit repeats on immutable isolated baseline");
 auto invalidPreview=s.call("doc_preview",bad);check(!invalidPreview.find("isError")->b&&!invalidPreview.find("structuredContent")->find("valid")->b&&invalidPreview.find("structuredContent")->find("failure_id"),"valid:false preview failure preserves exact candidate rejection custody");replay.set("id",*invalidPreview.find("structuredContent")->find("failure_id"));check(data(s.call("failure_replay",replay)).find("same_error")->b,"failed preview replay compares actual candidate rejection");
 const auto path=std::filesystem::temp_directory_path()/(id.str+".arkfailure.json");V exportArgs=V::makeObj();exportArgs.set("id",id);exportArgs.set("path",V::makeStr(path.string()));data(s.call("failure_export",exportArgs));check(s.call("failure_export",exportArgs).find("isError")->b,"failure export preserves an existing path");AgentSession reopened;V persisted=V::makeObj();persisted.set("path",V::makeStr(path.string()));persisted.set("expected_revision",V::makeNum(0));check(data(reopened.call("failure_replay",persisted)).find("same_error")->b&&reopened.document.features.empty(),"explicit local exported bundle replays after restart with live drawing untouched");{std::ifstream in(path,std::ios::binary);std::string raw((std::istreambuf_iterator<char>(in)),{});V bundle;check(arkjson::parse(raw,bundle),"exported bundle JSON custody");bundle.set("runtime_version",V::makeStr("0.0.0-test-different"));V kernel=*bundle.find("kernel");kernel.set("version",V::makeStr("test-different-kernel"));bundle.set("kernel",kernel);in.close();std::ofstream modified(path,std::ios::binary|std::ios::trunc);modified<<bundle.dump();modified.close();auto changedEnvironment=data(reopened.call("failure_replay",persisted));check(changedEnvironment.find("same_error")->b&&changedEnvironment.find("recorded_environment")->find("kernel")->find("version")->str=="test-different-kernel"&&changedEnvironment.find("environment_comparison")->find("runtime_changed")->b&&changedEnvironment.find("environment_comparison")->find("kernel_version_changed")->b,"replay retains recorded environment and reports version differences without claiming identical runtime/kernel");}std::filesystem::remove(path);
 const auto stale=s.call("failure_replay",json(R"({"id":"missing","expected_revision":0})"));check(stale.find("isError")->b&&documentToJson(s.document)==before,"stale replay authorization revision rejects atomically");
 const auto post=json(R"({"expected_revision":1,"commands":[{"op":"param.set","name":"probe","expr":1}],"checks":[{"id":"volume","query":{"tool":"native_inspect","args":{"id":4},"path":"report.volume_mm3"},"op":"eq","value":0}]})");auto rejected=s.call("doc_apply",post);check(rejected.find("isError")->b&&rejected.find("structuredContent")->find("failure_id")&&documentToJson(s.document)==before,"postcondition failure is recorded after rollback");replay.set("id",*rejected.find("structuredContent")->find("failure_id"));check(data(s.call("failure_replay",replay)).find("same_error")->b,"same failed postcondition is observed on isolated replay");
 for(int i=0;i<10;++i)s.call("doc_apply",bad);check(data(s.call("failure_info",V::makeObj())).find("records")->arr.size()==8,"local rejection store stays bounded");
}
void preview(){AgentSession s;base(s);const auto baseline=documentToJson(s.document);auto recipe=json(R"({"expected_revision":1,"commands":[{"op":"feature.add","type":"native_solid","name":"Fitted","inputs":[4,2],"native":{"op":"tube_end_fit","mode":"envelope","end":"start"},"p":{"max_extension":0}}]})");recipe.set("detail",V::makeStr("changes"));auto out=data(s.call("doc_preview",recipe));check(out.find("before")->find("partial")->b&&out.find("after")->find("partial")->b,"partial change summaries are explicitly opt-in");check(out.find("valid")->b&&out.find("candidate_cached")->b&&out.find("changed_feature_ids")&&out.find("end_fit_evidence")->arr.size()==1,"real evaluated end-fit preview gives selected changed IDs and exact fit evidence");check(s.revision==1&&documentToJson(s.document)==baseline,"preview preserves live CAD");V capture=json(R"({"id":5,"expected_revision":1,"view":"front"})");capture.set("candidate_id",*out.find("candidate_id"));auto image=s.call("snapshot",capture);check(!image.find("isError")->b&&image.find("content")->arr.size()==2&&!image.find("structuredContent")->find("visual_evidence")->find("committed")->b,"fitted candidate supplies actual uncommitted image pixels");data(s.call("doc_apply",*out.find("apply")));check(s.revision==2,"explicit candidate apply publishes revision once");}
void semanticRepeats(){
 AgentSession s;data(s.call("doc_apply",json(R"({"expected_revision":0,"commands":[{"op":"param.set","name":"width","expr":20},{"op":"feature.add","type":"box","name":"Base","p":{"dx":"width","dy":30,"dz":10}}]})")));
 const auto authoring=iterationAuthoring(s.document).dump();
 const auto firstArgs=json(R"({"expected_revision":1,"actor":{"kind":"agent","id":"first"},"motivation":"initial strategy","commands":[{"op":"feature.edit","id":"Missing","p":{"dx":25,"dy":"width"}}]})");
 const auto first=s.call("doc_apply",firstArgs);check(first.find("isError")->b&&first.find("structuredContent")->find("repeat_count")->num==1,"first actual command rejection captured");const auto id=*first.find("structuredContent")->find("failure_id");
 UsageReceipt usage;usage.id="repeat-provider-usage";usage.source="studio_assistant";usage.provenance="provider_response";usage.model="test-model";usage.inputTokens=50;usage.outputTokens=10;usage.totalTokens=60;usage.reportedResponses=1;std::string reason;check(addUsageReceipt(s.document,usage,&reason)==UsageRecordResult::Added,"real provider usage ledger changes without changing authoring");
 auto reordered=json(R"({"commands":[{"p":{"dy":"width","dx":25},"id":"Missing","op":"feature.edit"}],"motivation":"revised explanation","actor":{"id":"second","kind":"agent"},"expected_revision":1})");auto second=s.call("doc_apply",reordered);check(second.find("structuredContent")->find("repeat_count")->num==2&&second.find("structuredContent")->find("previous_failure_id")->str==id.str,"key reordering, caller metadata and provider usage keep semantic failure identity");
 data(s.call("doc_apply",json(R"({"expected_revision":1,"commands":[{"op":"param.set","name":"width","expr":21}]})")));data(s.call("doc_apply",json(R"({"expected_revision":2,"commands":[{"op":"param.set","name":"width","expr":20}]})")));check(iterationAuthoring(s.document).dump()==authoring,"new iteration history returns to identical authored inputs");reordered.set("expected_revision",V::makeNum(3));auto third=s.call("doc_apply",reordered);check(third.find("structuredContent")->find("repeat_count")->num==3&&third.find("structuredContent")->find("repeated_failure_guidance"),"same recipe after changed history/revision retains advisory repeat evidence");
 auto infoArgs=V::makeObj();infoArgs.set("id",id);auto record=data(s.call("failure_info",infoArgs));check(record.find("record")->find("request")->dump()==firstArgs.dump()&&!record.find("record")->find("baseline"),"diagnostic key never replaces original caller request or exposes full baseline");auto replay=infoArgs;replay.set("expected_revision",V::makeNum(3));const auto live=documentToJson(s.document);auto proof=data(s.call("failure_replay",replay));check(proof.find("same_error")->b&&proof.find("baseline_revision")->num==1&&documentToJson(s.document)==live,"semantic repeats retain immutable original baseline for isolated replay");
 auto changed=json(R"({"expected_revision":3,"commands":[{"op":"feature.edit","id":"Missing","p":{"dx":26,"dy":"width"}}]})");check(s.call("doc_apply",changed).find("structuredContent")->find("repeat_count")->num==1,"actual parameter changes are a different command recipe even with the same rejection");
 data(s.call("doc_apply",json(R"({"expected_revision":3,"commands":[{"op":"param.set","name":"width","expr":22}]})")));reordered.set("expected_revision",V::makeNum(4));check(s.call("doc_apply",reordered).find("structuredContent")->find("repeat_count")->num==1,"actual authoring baseline change starts a new failure identity");
 auto checks=json(R"({"expected_revision":4,"commands":[{"op":"param.set","name":"width","expr":22}],"checks":[{"query":{"tool":"doc_info","args":{},"path":"feature_count"},"op":"eq","value":99}]})");auto failedCheck=s.call("doc_apply",checks);check(failedCheck.find("isError")->b&&failedCheck.find("structuredContent")->find("repeat_count")->num==1,"failed postcondition recipe captured");check(s.call("doc_apply",checks).find("structuredContent")->find("repeat_count")->num==2,"same recipe includes exact checks in repeat identity");for(auto& entry:checks.obj)if(entry.first=="checks")entry.second.arr[0].set("value",V::makeNum(100));check(s.call("doc_apply",checks).find("structuredContent")->find("repeat_count")->num==1,"actual postcondition target change is a different recipe");
}
void sevenSolids(){
 AgentSession s;V frame=json(R"({"op":"feature.add","type":"construction_frame","name":"Seven separate members","native":{"profiles":[{"name":"R","section":"rect","width":20,"height":16,"wall":2}],"nodes":[],"members":[]}})");V native=*frame.find("native"),nodes=V::makeArr(),members=V::makeArr();for(int i=0;i<7;++i){for(int end=0;end<2;++end){V node=V::makeObj(),xyz=V::makeArr();node.set("name",V::makeStr("n"+std::to_string(i)+std::to_string(end)));xyz.arr={V::makeNum(end*100),V::makeNum(i*100),V::makeNum(0)};node.set("xyz",xyz);nodes.arr.push_back(node);}V member=V::makeObj();member.set("name",V::makeStr("member"+std::to_string(i)));member.set("profile",V::makeStr("R"));member.set("start",V::makeStr("n"+std::to_string(i)+"0"));member.set("end",V::makeStr("n"+std::to_string(i)+"1"));members.arr.push_back(member);}native.set("nodes",nodes);native.set("members",members);frame.set("native",native);V args=V::makeObj(),commands=V::makeArr();commands.arr.push_back(frame);args.set("expected_revision",V::makeNum(0));args.set("commands",commands);data(s.call("doc_apply",args));const auto before=documentToJson(s.document);auto failed=s.call("doc_apply",json(R"({"expected_revision":1,"commands":[{"op":"feature.add","type":"native_solid","name":"Rejected compound transform","inputs":[1],"native":{"op":"transform"},"p":{"tx":10}}]})"));check(failed.find("isError")->b&&failed.dump().find("contains 7 solids")!=std::string::npos,"actual seven-solid operand census causes native single-solid rejection");V replay=V::makeObj();replay.set("expected_revision",V::makeNum(1));replay.set("id",*failed.find("structuredContent")->find("failure_id"));check(data(s.call("failure_replay",replay)).find("same_error")->b&&documentToJson(s.document)==before,"real seven-solid failure replays unchanged");}
}
int main(){try{custody();preview();semanticRepeats();sevenSolids();std::cout<<"Failure custody/replay and end-fit preview contracts passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
